contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // params: receiver and amount to attempt to send from c
    function run(address receiver, uint amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000);
        require(address(this).balance >= 0);

        // observe contract balance before
        uint balBefore = address(c).balance;

        // perform the call and record whether it reverted
        bool reverted;
        c.sendTo(receiver, amount); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        // observe contract balance after
        uint balAfter = address(c).balance;

        // General rule: sendTo never increases the contract's balance
        // (i.e., balAfter <= balBefore) — holds for all inputs
        assert(balAfter <= balBefore || reverted == true);
    }

    receive() external payable {}
}

